return ['domain'=>'simple-ldap-login','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nl_NL','project-id-version'=>'Simple LDAP Login 2.0.0','pot-creation-date'=>'2026-10-30T15:26:17+00:00','po-revision-date'=>'2026-10-30T15:26:17+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['Simple LDAP Login'=>'Simple LDAP Login','https://github.com/clifgriffin/simple-ldap-login'=>'https://github.com/clifgriffin/simple-ldap-login','Connect WordPress accounts to Active Directory or OpenLDAP.'=>'Verbind WordPress-accounts met Active Directory of OpenLDAP.','Clif Griffin Development Inc.'=>'Clif Griffin Development Inc.','https://clifgriffin.com'=>'https://clifgriffin.com','User data'=>'Gebruikersgegevens','Single sign-on'=>'Single sign-on','Custom user fields'=>'Aangepaste gebruikersvelden','Copy LDAP fields, such as phone number or department, to WordPress at login. Your theme or other plugins can use these values.'=>'Kopieer LDAP-velden, zoals telefoonnummer of afdeling, naar WordPress bij inloggen. Je thema of andere plugins kunnen deze waarden gebruiken.','Field mappings'=>'Veldkoppelingen','One mapping per line: LDAP attribute:WordPress meta key:type. Example: %1$s. Types: %2$s or %3$s.'=>'Één mapping per regel: LDAP-attribuut:WordPress meta sleutel:type. Voorbeeld: %1$s. Typen: %2$s of %3$s.','Custom field storage'=>'Opslag van aangepaste velden','Leave the defaults unless your integration uses different user meta keys.'=>'Laat de standaardinstellingen staan, tenzij uw integratie andere gebruikersmeta-sleutels gebruikt.','LDAP value suffix'=>'LDAP-waarde suffix','Stores the LDAP value, such as phone_ldap.'=>'Slaat de LDAP-waarde op, zoals phone_ldap.','WordPress value suffix'=>'WordPress-waarde suffix','Stores the editable WordPress value, such as phone_wp.'=>'Slaat de bewerkbare WordPress-waarde op, zoals phone_wp.','Single sign-on (SSO)'=>'Single sign-on (SSO)','Sign users in to WordPress after your web server authenticates them.'=>'Meld gebruikers aan bij WordPress nadat je webserver hen heeft geverifieerd.','Enable single sign-on'=>'Schakel single sign-on in','Users do not need a second login for WordPress.'=>'Gebruikers hebben geen tweede inlog nodig voor WordPress.','Configure your web server to authenticate users and set REMOTE_USER. Enter an LDAP search account on Connection.'=>'Configureer je webserver om gebruikers te verifiëren en stel REMOTE_USER in. Voer een LDAP-zoekaccount in bij Verbinding.','Do not copy browser headers into REMOTE_USER. Block access that bypasses web server authentication.'=>'Kopieer geen browserheaders naar REMOTE_USER. Blokkeer toegang die de authenticatie van de webserver omzeilt.','Web server authentication'=>'Webserverauthenticatie','REMOTE_USER is present.'=>'REMOTE_USER is aanwezig.','REMOTE_USER is missing. Check the web server configuration.'=>'REMOTE_USER ontbreekt. Controleer de configuratie van de webserver.','The update was stopped. Activate Simple LDAP Login Pro to restore LDAP login.'=>'De update is gestopt. Activeer Simple LDAP Login Pro om LDAP-inloggen te herstellen.','Update blocked: This package does not include all Pro files. To install Free, deactivate the plugin first. Your installed files and settings are unchanged.'=>'Update geblokkeerd: Dit pakket bevat niet alle Pro-bestanden. Deactiveer de plugin eerst om Free te installeren. Uw geïnstalleerde bestanden en instellingen blijven ongewijzigd.','WordPress could not reactivate the plugin.'=>'WordPress kon de plugin niet opnieuw activeren.','Simple LDAP Login needs PHP 8.1 or later.'=>'Simple LDAP Login heeft PHP 8.1 of later nodig.','Plugin files are missing. Reinstall Simple LDAP Login from the release ZIP.'=>'Pluginbestanden ontbreken. Herinstalleer Simple LDAP Login vanuit de release ZIP.','You do not have permission to change these settings.'=>'U heeft geen toestemming om deze instellingen te wijzigen.','The settings scope has changed. Open the settings page and try again.'=>'De instellingen scope is gewijzigd. Open de instellingenpagina en probeer het opnieuw.','You do not have permission to view these settings.'=>'U heeft geen toestemming om deze instellingen te bekijken.','Network settings'=>'Netwerkinstellingen','Site settings'=>'Site-instellingen','LDAP login settings'=>'LDAP-aanmeldinstellingen','Connect to LDAP, then test a login before enabling authentication.'=>'Verbind met LDAP en test een aanmelding voordat u authenticatie inschakelt.','LDAP login and SSO are disabled by SLL_DISABLE_LDAP in wp-config.php.'=>'LDAP-aanmelding en SSO zijn uitgeschakeld door SLL_DISABLE_LDAP in wp-config.php.','Your saved settings use SSO or custom user fields. Install Simple LDAP Login Pro to use these features. Your settings are kept.'=>'Uw opgeslagen instellingen gebruiken SSO of aangepaste gebruikersvelden. Installeer Simple LDAP Login Pro om deze functies te gebruiken. Uw instellingen worden bewaard.','The saved LDAP search password cannot be read. Enter it again on the Connection tab.'=>'Het opgeslagen LDAP-zoekwachtwoord kan niet worden gelezen. Voer het opnieuw in op het tabblad Verbinding.','PHP LDAP is missing. Ask your host to install it before enabling LDAP login.'=>'PHP LDAP ontbreekt. Vraag je host om het te installeren voordat je LDAP-login inschakelt.','LDAP passwords are sent without encryption. Use StartTLS or LDAPS if your server supports it.'=>'LDAP-wachtwoorden worden zonder encryptie verzonden. Gebruik StartTLS of LDAPS als je server dit ondersteunt.','Save settings'=>'Instellingen opslaan','Settings on other tabs are kept.'=>'Instellingen op andere tabbladen blijven behouden.','LDAP connection'=>'LDAP-verbinding','LDAP login'=>'LDAP-login','Enable LDAP authentication.'=>'Schakel LDAP-authenticatie in.','Directory type'=>'Directorytype','Active Directory'=>'Active Directory','OpenLDAP / other LDAP directory'=>'OpenLDAP / andere LDAP-directory','LDAP servers'=>'LDAP-servers','One hostname or IP address per line. Servers are tried in order.'=>'Één hostnaam of IP-adres per regel. Servers worden in volgorde geprobeerd.','Base DN'=>'Basis DN','Where to search for users. Example: DC=example,DC=org.'=>'Waar te zoeken naar gebruikers. Voorbeeld: DC=example,DC=org.','Username suffix'=>'Gebruikersnaam suffix','Added to usernames without a domain. Example: @example.org.'=>'Toegevoegd aan gebruikersnamen zonder domein. Voorbeeld: @example.org.','Windows domain'=>'Windows-domein','Short domain name, such as EXAMPLE. Takes priority over the username suffix.'=>'Korte domeinnaam, zoals EXAMPLE. Heeft prioriteit boven de gebruikersnaam suffix.','Connection security'=>'Verbindingsbeveiliging','TLS requires a trusted server certificate.'=>'TLS vereist een vertrouwd servercertificaat.','StartTLS (recommended)'=>'StartTLS (aanbevolen)','LDAPS'=>'LDAPS','Unencrypted LDAP'=>'Ongecodeerde LDAP','Unencrypted LDAP requires permission on the Advanced tab.'=>'Ongecodeerde LDAP vereist toestemming op het tabblad Geavanceerd.','Port'=>'Poort','389 for StartTLS; 636 for LDAPS.'=>'389 voor StartTLS; 636 voor LDAPS.','Search subfolders'=>'Zoek submappen','Search all organizational units below the Base DN.'=>'Zoek alle organisatorische eenheden onder de Basis DN.','LDAP search account'=>'LDAP-zoekaccount','An LDAP account with read access to users and groups.'=>'Een LDAP-account met leesrechten voor gebruikers en groepen.','Search account'=>'Zoekaccount','LDAP bind DN or account name.'=>'LDAP bind DN of accountnaam.','Search account password'=>'Wachtwoord zoekaccount','Leave blank to keep the saved password.'=>'Laat leeg om het opgeslagen wachtwoord te behouden.','Login rules'=>'Inlogregels','Require LDAP passwords'=>'Vereis LDAP-wachtwoorden','Block WordPress passwords except for recovery access.'=>'Blokkeer WordPress-wachtwoorden, behalve voor hersteltoegang.','Local recovery access'=>'Lokale hersteltoegang','Selected administrators'=>'Geselecteerde beheerders','All super administrators (legacy)'=>'Alle superbeheerders (legacy)','All administrators (legacy)'=>'Alle beheerders (legacy)','Off'=>'Uit','Choose who can use a WordPress password when LDAP passwords are required.'=>'Kies wie een WordPress-wachtwoord kan gebruiken wanneer LDAP-wachtwoorden vereist zijn.','Automatic account creation'=>'Automatische accountcreatie','Create a WordPress account on the first successful LDAP login.'=>'Maak een WordPress-account aan bij de eerste succesvolle LDAP-login.','Default role'=>'Standaardrol','For new accounts only.'=>'Alleen voor nieuwe accounts.','Required groups'=>'Vereiste groepen','One group name per line. Users must belong to at least one. Leave blank to allow all LDAP users.'=>'Één groepsnaam per regel. Gebruikers moeten tot ten minste één behoren. Laat leeg om alle LDAP-gebruikers toe te staan.','Recovery accounts'=>'Herstelaccounts','For Selected administrators only. Use separate local accounts with WordPress passwords. Hold Ctrl or Command to select multiple accounts.'=>'Alleen voor Geselecteerde beheerders. Gebruik aparte lokale accounts met WordPress-wachtwoorden. Houd Ctrl of Command ingedrukt om meerdere accounts te selecteren.','Connection options'=>'Verbindingsopties','Change these only if the default values do not work with your directory.'=>'Wijzig deze alleen als de standaardwaarden niet werken met je directory.','LDAP timeout (seconds)'=>'LDAP-timeout (seconden)','Maximum wait for an LDAP operation. Default: 5 seconds.'=>'Maximale wachttijd voor een LDAP-operatie. Standaard: 5 seconden.','Login attribute'=>'Inlogattribuut','Attribute used to find users. Default: uid.'=>'Attribuut dat wordt gebruikt om gebruikers te vinden. Standaard: uid.','Allow unencrypted LDAP'=>'Sta ongecodeerde LDAP toe','Allow passwords to be sent without encryption.'=>'Sta toe dat wachtwoorden zonder encryptie worden verzonden.','Group search'=>'Groep zoeken','Group base DN'=>'Groep basis DN','Leave blank to use the user Base DN.'=>'Laat leeg om de gebruikers Basis DN te gebruiken.','Group name attribute'=>'Groep naam attribuut','Default: cn.'=>'Standaard: cn.','Group member attribute'=>'Groep lid attribuut','Default: memberUid. Use member or uniqueMember if groups store user DNs.'=>'Standaard: memberUid. Gebruik member of uniqueMember als groepen gebruikers DNs opslaan.','Profile attributes'=>'Profielattributen','LDAP attributes copied to new WordPress accounts.'=>'LDAP-attributen gekopieerd naar nieuwe WordPress-accounts.','First name attribute'=>'Voornaam attribuut','Last name attribute'=>'Achternaam attribuut','Email attribute'=>'E-mail attribuut','Website attribute'=>'Website attribuut','Data retention'=>'Gegevensretentie','Delete settings when removing the plugin'=>'Verwijder instellingen bij het verwijderen van de plugin','Delete saved settings and LDAP credentials when WordPress deletes the plugin. Keep user accounts.'=>'Verwijder opgeslagen instellingen en LDAP-gegevens wanneer WordPress de plugin verwijdert. Houd gebruikersaccounts.','Test LDAP login'=>'Test LDAP-login','Save your settings, then run both tests. Keep this administrator session open.'=>'Sla uw instellingen op en voer vervolgens beide tests uit. Houd deze beheerderssessie open.','Tests check the connection, password, and required groups. They do not create accounts or sign users in.'=>'Tests controleren de verbinding, het wachtwoord en de vereiste groepen. Ze maken geen accounts aan of loggen gebruikers in.','After both tests pass, enable LDAP and try logging in from another browser.'=>'Nadat beide tests zijn geslaagd, schakel LDAP in en probeer in te loggen vanuit een andere browser.','Recovery'=>'Herstel','If you are locked out, rename the simple-ldap-login folder using your hosting file manager. Log in with a WordPress administrator password, then restore the folder and correct the settings.'=>'Als u bent buitengesloten, hernoem de simple-ldap-login map met uw hosting-bestandsbeheerder. Log in met een WordPress-beheerderswachtwoord, herstel de map en corrigeer de instellingen.','For certificate errors, ask your host to configure the trusted LDAP certificate authority.'=>'Voor certificaatfouten, vraag uw host om de vertrouwde LDAP-certificeringsinstantie te configureren.','LDAP tests'=>'LDAP-tests','Tests use saved settings.'=>'Tests gebruiken opgeslagen instellingen.','1. Test connection'=>'1. Test verbinding','Connect to LDAP and test the search account, if set.'=>'Verbind met LDAP en test het zoekaccount, indien ingesteld.','Test connection'=>'Test verbinding','2. Test login'=>'2. Test login','Check an LDAP username, password, and group membership.'=>'Controleer een LDAP-gebruikersnaam, wachtwoord en groepslidmaatschap.','LDAP username'=>'LDAP-gebruikersnaam','LDAP password'=>'LDAP-wachtwoord','Settings saved.'=>'Instellingen opgeslagen.','Connection test passed.'=>'Verbindingstest geslaagd.','Cannot connect to LDAP. Check the server, port, TLS certificate, and search account.'=>'Kan geen verbinding maken met LDAP. Controleer de server, poort, TLS-certificaat en zoekaccount.','LDAP login test passed. No account was created.'=>'LDAP-login test geslaagd. Er is geen account aangemaakt.','LDAP login test failed. Check the username, password, and required groups.'=>'LDAP-login test mislukt. Controleer de gebruikersnaam, het wachtwoord en de vereiste groepen.','Could not save settings. Check the values and try again.'=>'Kon instellingen niet opslaan. Controleer de waarden en probeer het opnieuw.','Connection'=>'Verbinding','Access'=>'Toegang','Advanced'=>'Geavanceerd','Troubleshooting'=>'Probleemoplossing','Your LDAP login is valid, but you need a WordPress account. Contact your site administrator.'=>'Uw LDAP-login is geldig, maar u heeft een WordPress-account nodig. Neem contact op met uw sitebeheerder.','Your LDAP username is not a valid WordPress username. Contact your site administrator.'=>'Uw LDAP-gebruikersnaam is geen geldige WordPress-gebruikersnaam. Neem contact op met uw sitebeheerder.','The default WordPress role is not available. Contact your site administrator.'=>'De standaard WordPress-rol is niet beschikbaar. Neem contact op met uw sitebeheerder.','Could not create your WordPress account. Contact your site administrator.'=>'Kon uw WordPress-account niet aanmaken. Neem contact op met uw sitebeheerder.','Use your WordPress password for this recovery account.'=>'Gebruik uw WordPress-wachtwoord voor dit herstelaccount.','License'=>'Licentie','Get Pro'=>'Krijg Pro','Could not check your license. Pro features remain active. Try again on the License tab.'=>'Kon je licentie niet controleren. Pro-functies blijven actief. Probeer het opnieuw op het tabblad Licentie.','Your Pro license has expired. Single sign-on and custom field updates are off. Renew your license, then select Check license on the License tab.'=>'Je Pro-licentie is verlopen. Single sign-on en updates van aangepaste velden zijn uitgeschakeld. Vernieuw je licentie en selecteer vervolgens Licentie controleren op het tabblad Licentie.','Activate a Pro license on the License tab to use single sign-on and custom user fields.'=>'Activeer een Pro-licentie op het tabblad Licentie om single sign-on en aangepaste gebruikersvelden te gebruiken.','Simple LDAP Login Pro'=>'Simple LDAP Login Pro','Give staff fewer login prompts and keep user details in sync with LDAP.'=>'Geef personeel minder inlogverzoeken en houd gebruikersgegevens gesynchroniseerd met LDAP.','Let staff open WordPress without another login prompt. Requires authentication on your web server, such as Kerberos or NTLM.'=>'Laat personeel WordPress openen zonder een ander inlogverzoek. Vereist authenticatie op je webserver, zoals Kerberos of NTLM.','Copy phone numbers, departments, and other LDAP fields to WordPress at login. Use these values in your theme or other plugins.'=>'Kopieer telefoonnummers, afdelingen en andere LDAP-velden naar WordPress bij inloggen. Gebruik deze waarden in je thema of andere plugins.','View plans'=>'Bekijk plannen','Open checkout in a new tab'=>'Open afrekenen in een nieuw tabblad','Plans and checkout use PaidCommunities. It receives your IP address and browser details.'=>'Plannen en afrekeningen gebruiken PaidCommunities. Het ontvangt je IP-adres en browsergegevens.','After purchase, install the Pro ZIP from your receipt. Your LDAP settings will stay in place.'=>'Installeer na aankoop de Pro ZIP van je ontvangstbewijs. Je LDAP-instellingen blijven behouden.','License status updated.'=>'Licentiestatus bijgewerkt.','Could not verify the license. Check your key and connection, then try again.'=>'Kon de licentie niet verifiëren. Controleer je sleutel en verbinding, en probeer het opnieuw.','Pro license'=>'Pro-licentie','Enter the license key from your purchase receipt.'=>'Voer de licentiesleutel in van je aankoopbewijs.','Not activated'=>'Niet geactiveerd','Expired'=>'Verlopen','Inactive'=>'Inactief','License status'=>'Licentiestatus','Active'=>'Actief','Data shared with PaidCommunities'=>'Gegevens gedeeld met PaidCommunities','Activation sends your license key, site domain, plugin version, and server IP address to PaidCommunities. License checks send the same site details.'=>'Activatie verzendt je licentiesleutel, site-domein, pluginversie en server-IP-adres naar PaidCommunities. Licentiecontroles verzenden dezelfde sitegegevens.','License key'=>'Licentiesleutel','Activate license'=>'Licentie activeren','Deactivate license'=>'Licentie deactiveren','Check license'=>'Licentie controleren','Select a license action.'=>'Selecteer een licentieactie.','Activating license…'=>'Licentie activeren…','Deactivating license…'=>'Licentie deactiveren…','License error'=>'Licentiefout','License updated'=>'Licentie bijgewerkt','Pro plans'=>'Pro-plannen','Loading plans…'=>'Plannen laden…','Could not load plans. Open checkout in a new tab.'=>'Kon plannen niet laden. Open afrekenen in een nieuw tabblad.','LDAP login failed. Check your username and password or contact your site administrator.'=>'LDAP-login mislukt. Controleer uw gebruikersnaam en wachtwoord of neem contact op met uw sitebeheerder.','Your account is not allowed to log in to this site.'=>'Uw account mag niet inloggen op deze site.','LDAP login is unavailable. Contact your site administrator.'=>'LDAP-login is niet beschikbaar. Neem contact op met uw sitebeheerder.','PHP OpenSSL is required to save the LDAP search password.'=>'PHP OpenSSL is vereist om het LDAP-zoekwachtwoord op te slaan.','Could not read or save the LDAP search password. Enter it again. If this continues, ask your host to check OpenSSL and the encryption key.'=>'Kon het LDAP-zoekwachtwoord niet lezen of opslaan. Voer het opnieuw in. Als dit aanhoudt, vraag uw host om OpenSSL en de versleutelingssleutel te controleren.','Select a recovery account on the Access tab, or turn local recovery access Off.'=>'Selecteer een herstelaccount op het tabblad Toegang, of zet de lokale hersteltoegang uit.','Enable Allow unencrypted LDAP on the Advanced tab, or choose StartTLS or LDAPS.'=>'Schakel Toestaan van ongecodeerde LDAP in op het tabblad Geavanceerd, of kies StartTLS of LDAPS.','A custom field mapping uses a protected or invalid WordPress user meta key.'=>'Een aangepaste veldmapping gebruikt een beschermde of ongeldige WordPress-gebruikersmeta-sleutel.','Enter a Base DN and at least one LDAP server before enabling LDAP login.'=>'Voer een Basis DN in en ten minste één LDAP-server voordat u LDAP-login inschakelt.','WordPress could not save the settings. Try again.'=>'WordPress kon de instellingen niet opslaan. Probeer het opnieuw.','LDAP protocol version'=>'LDAP-protocolversie','LDAP timeout'=>'LDAP-timeout','Check the submitted settings. No changes were saved.'=>'Controleer de ingediende instellingen. Geen wijzigingen zijn opgeslagen.','Check %s. No changes were saved.'=>'Controleer %s. Geen wijzigingen zijn opgeslagen.']];